function results = process_suppfig6ko_exrai(processedRoot,generatedRoot,cfg)
% PROCESS_SUPPFIG6KO_EXRAI Derive Supplemental Fig. 6k-o analysis tables.
%
% The inputs are the preprocessing MAT files generated by the Fig. 3f/i/l
% workflow. No manuscript source-data table is read by this function.

if nargin < 3 || isempty(cfg), cfg = suppfig6ko_config(); end
assert(isfolder(processedRoot), ...
    'Fig. 3 ExRaiAKAR2 processed folder not found: %s',processedRoot);
if ~isfolder(generatedRoot), mkdir(generatedRoot); end

fprintf('\n1/5 Exporting the representative fitted channels...\n');
panelK = makePanelK(processedRoot,cfg);
writetable(panelK,fullfile(generatedRoot,cfg.files.panel_k));

fprintf('2/5 Exporting representative baseline traces...\n');
panelL = makePanelL(processedRoot,cfg);
writetable(panelL,fullfile(generatedRoot,cfg.files.panel_l));

fprintf('3/5 Calculating RAC-peak repeatability...\n');
[panelM,panelMStats] = makePanelM(processedRoot,cfg);
writetable(panelM,fullfile(generatedRoot,cfg.files.panel_m));
writetable(panelMStats,fullfile(generatedRoot,cfg.files.panel_m_stats));

fprintf('4/5 Comparing conventional and RAC-peak normalisation...\n');
panelN = makePanelN(processedRoot,cfg);
writetable(panelN,fullfile(generatedRoot,cfg.files.panel_n));

fprintf('5/5 Calculating the between-animal variability comparison...\n');
[panelO,panelOStats,panelOBootstrap] = makePanelO(processedRoot,cfg);
writetable(panelO,fullfile(generatedRoot,cfg.files.panel_o));
writetable(panelOStats,fullfile(generatedRoot,cfg.files.panel_o_stats));
writetable(panelOBootstrap,fullfile(generatedRoot,cfg.files.panel_o_bootstrap));

results = struct('generated_source_root',generatedRoot, ...
    'panel_k',panelK,'panel_l',panelL,'panel_m',panelM, ...
    'panel_m_statistics',panelMStats,'panel_n',panelN, ...
    'panel_o',panelO,'panel_o_statistics',panelOStats, ...
    'panel_o_bootstrap',panelOBootstrap);
fprintf('\nGenerated panel tables written to:\n%s\n',generatedRoot);
end

function T = makePanelK(root,cfg)
S = loadPreprocessed(root,cfg.panel_k_treatment,cfg.panel_k_subject);
[t,fit405,signal465] = sameLength(S.fpx_time,S.fpx_fit405,S.fpx_465);
show = t>=cfg.panel_k_window_min(1) & t<=cfg.panel_k_window_min(2) & ...
    isfinite(t) & isfinite(fit405) & isfinite(signal465);
T = table(t(show),fit405(show),signal465(show),'VariableNames', ...
    {'Time_min','Fitted_405_nm','Signal_465_nm'});
end

function T = makePanelL(root,cfg)
T = table();
for i = 1:numel(cfg.panel_l_subjects)
    subject = cfg.panel_l_subjects{i};
    S = loadPreprocessed(root,cfg.panel_l_treatment,subject);
    [t,y] = sameLength(S.fpx_time,S.fpx_dRR);
    show = t>=cfg.panel_l_window_min(1) & t<=cfg.panel_l_window_min(2) & ...
        isfinite(t) & isfinite(y);
    Ti = table(repmat(string(subject),nnz(show),1),t(show),y(show), ...
        'VariableNames',{'Subject','Time_min','dRR'});
    T = [T;Ti]; %#ok<AGROW>
end
end

function [T,stats] = makePanelM(root,cfg)
peaks = nan(numel(cfg.subjects),2);
for i = 1:numel(cfg.subjects)
    for administration = 1:2
        S = loadPreprocessed(root,cfg.panel_m_treatments{administration}, ...
            cfg.subjects{i});
        [t,y] = sameLength(S.fpx_time,S.fpx_dRR);
        valid = isfinite(t) & isfinite(y);
        t = t(valid); y = y(valid);
        ys = smoothBySeconds(t,y,cfg.smooth_sec);
        use = t>=cfg.rac_peak_window_min(1) & ...
            t<=cfg.rac_peak_window_min(2);
        if any(use), peaks(i,administration) = max(ys(use),[],'omitnan'); end
    end
end
complete = all(isfinite(peaks),2);
T = table(string(cfg.subjects(complete))',peaks(complete,1),peaks(complete,2), ...
    'VariableNames',{'Subject','RAC_Peak_Administration_1', ...
    'RAC_Peak_Administration_2'});
assert(~isempty(T),'No complete RV/RG subject pairs were found.');
stats = repeatabilityICC(T,cfg);
end

function T = makePanelN(root,cfg)
traces = repmat(struct('subject','','time',[],'conventional',[], ...
    'scaled',[]),numel(cfg.panel_n_subjects),1);
for i = 1:numel(cfg.panel_n_subjects)
    subject = cfg.panel_n_subjects{i};
    VG = loadPreprocessed(root,cfg.panel_n_treatment,subject);
    RV = loadPreprocessed(root,'RV',subject);
    [t,x] = sameLength(VG.fpx_time,VG.fpx_dRR);
    xs = smoothBySeconds(t,x,cfg.smooth_sec);
    base = t>=cfg.baseline_window_min(1) & ...
        t<=cfg.baseline_window_min(2) & isfinite(t) & isfinite(xs);
    baselineMean = mean(xs(base),'omitnan');
    baselineSD = std(xs(base),0,'omitnan');
    assert(isfinite(baselineSD) && baselineSD>0, ...
        'Invalid VG baseline SD for subject %s.',subject);

    [tr,xr] = sameLength(RV.fpx_time,RV.fpx_dRR);
    valid = isfinite(tr) & isfinite(xr);
    tr = tr(valid); xr = xr(valid);
    rvSmooth = smoothBySeconds(tr,xr,cfg.smooth_sec);
    rvPeak = max(rvSmooth,[],'omitnan');
    assert(isfinite(rvPeak) && rvPeak>0, ...
        'Invalid RV peak for subject %s.',subject);

    traces(i).subject = subject;
    traces(i).time = t;
    traces(i).conventional = (xs-baselineMean)./baselineSD;
    traces(i).scaled = xs./rvPeak;
end

time = traces(1).time(:);
time = time(isfinite(time));
T = table(time,'VariableNames',{'Time_min'});
for i = 1:numel(traces)
    subjectName = matlab.lang.makeValidName(traces(i).subject);
    T.([subjectName '_conventional_z']) = interpolateTrace( ...
        traces(i).time,traces(i).conventional,time);
    T.([subjectName '_RACnormalised']) = interpolateTrace( ...
        traces(i).time,traces(i).scaled,time);
end
end

function [T,stats,bootstrapStats] = makePanelO(root,cfg)
n = numel(cfg.subjects);
rawAUC = nan(n,1); zAUC = nan(n,1); scaledAUC = nan(n,1);
rvPeak = nan(n,1); baselineSD = nan(n,1); nDrug = nan(n,1);
for i = 1:n
    subject = cfg.subjects{i};
    VG = loadPreprocessed(root,cfg.panel_o_treatment,subject);
    RV = loadPreprocessed(root,'RV',subject);
    [t,x] = sameLength(VG.fpx_time,VG.fpx_dRR);
    xs = smoothBySeconds(t,x,cfg.smooth_sec);

    [tr,xr] = sameLength(RV.fpx_time,RV.fpx_dRR);
    rvSmooth = smoothBySeconds(tr,xr,cfg.smooth_sec);
    peakMask = tr>=cfg.rac_peak_window_min(1) & ...
        tr<=cfg.rac_peak_window_min(2) & isfinite(tr) & isfinite(rvSmooth);
    assert(any(peakMask),'No valid RV RAC-peak samples for subject %s.',subject);
    rvPeak(i) = max(rvSmooth(peakMask),[],'omitnan');

    base = t>=cfg.baseline_window_min(1) & t<=cfg.baseline_window_min(2);
    drug = t>=cfg.gbr_auc_window_min(1) & t<=cfg.gbr_auc_window_min(2);
    baselineMean = mean(xs(base),'omitnan');
    baselineSD(i) = std(xs(base),0,'omitnan');
    z = (xs-baselineMean)./baselineSD(i);
    scaled = xs./rvPeak(i);
    rawAUC(i) = positiveAUC(t,xs,cfg.gbr_auc_window_min, ...
        cfg.carry_forward_tail);
    zAUC(i) = positiveAUC(t,z,cfg.gbr_auc_window_min, ...
        cfg.carry_forward_tail);
    scaledAUC(i) = positiveAUC(t,scaled,cfg.gbr_auc_window_min, ...
        cfg.carry_forward_tail);
    nDrug(i) = nnz(drug);
end

values = [rawAUC,zAUC,scaledAUC];
means = mean(values,1,'omitnan');
relative = values./means;
T = table(string(cfg.subjects)',rawAUC,zAUC,scaledAUC,rvPeak,baselineSD,nDrug, ...
    repmat(means(1),n,1),repmat(means(2),n,1),repmat(means(3),n,1), ...
    relative(:,1),relative(:,2),relative(:,3),'VariableNames', ...
    {'Subject','VG_GBR_raw_positiveAUC','VG_GBR_baseline_z_positiveAUC', ...
    'VG_GBR_RVpeak_scaled_positiveAUC','RV_peak','VG_baseline_SD', ...
    'N_drug_samples','Raw_positiveAUC_group_mean', ...
    'Baseline_z_positiveAUC_group_mean', ...
    'RVpeak_scaled_positiveAUC_group_mean', ...
    'Raw_positiveAUC_relative_to_group_mean', ...
    'Baseline_z_positiveAUC_relative_to_group_mean', ...
    'RVpeak_scaled_positiveAUC_relative_to_group_mean'});

sdValues = std(values,0,1,'omitnan');
cvValues = sdValues./abs(means);
stats = table({'Raw dR/R';'Baseline z-score';'RV-peak scaled'}, ...
    means(:),sdValues(:),cvValues(:),'VariableNames', ...
    {'Normalisation','Mean_AUC','Across_animal_SD','CV'});
bootstrapStats = variabilityBootstrap(values,cvValues,cfg);
end

function stats = repeatabilityICC(T,cfg)
subjects = categorical([T.Subject;T.Subject]);
peaks = [T.RAC_Peak_Administration_1;T.RAC_Peak_Administration_2];
long = table(subjects,peaks,'VariableNames',{'Subject','Peak'});
lme = fitlme(long,'Peak ~ 1 + (1|Subject)');
cp = covarianceParameters(lme);
if iscell(cp), subjectVariance = cp{1}; else, subjectVariance = cp; end
residualVariance = lme.MSE;
icc = subjectVariance/(subjectVariance+residualVariance);

rng(cfg.random_seed);
levels = unique(T.Subject,'stable');
bootICC = nan(cfg.n_bootstrap_icc,1);
for b = 1:cfg.n_bootstrap_icc
    sampled = levels(randi(numel(levels),numel(levels),1));
    Tb = table();
    for s = 1:numel(sampled)
        Tb = [Tb;T(T.Subject==sampled(s),:)]; %#ok<AGROW>
    end
    Tb.Subject = categorical(string(Tb.Subject));
    longB = table([Tb.Subject;Tb.Subject], ...
        [Tb.RAC_Peak_Administration_1;Tb.RAC_Peak_Administration_2], ...
        'VariableNames',{'Subject','Peak'});
    if numel(unique(longB.Subject))<2, continue; end
    try
        model = fitlme(longB,'Peak ~ 1 + (1|Subject)');
        cpB = covarianceParameters(model);
        if iscell(cpB), vs = cpB{1}; else, vs = cpB; end
        bootICC(b) = vs/(vs+model.MSE);
    catch
        % Some degenerate resamples cannot be fitted.
    end
end
ci = prctile(bootICC(isfinite(bootICC)),[2.5 97.5]);
stats = table(height(long),height(T),subjectVariance,residualVariance,icc, ...
    ci(1),ci(2),'VariableNames',{'N_Observations','N_Subjects', ...
    'SubjectVariance','ResidualVariance','ICC','ICC_CI_Lower','ICC_CI_Upper'});
end

function stats = variabilityBootstrap(values,cvValues,cfg)
rng(cfg.random_seed);
values = values(all(isfinite(values),2),:);
n = size(values,1);
delta = nan(cfg.n_bootstrap_variability,3);
ratio = nan(cfg.n_bootstrap_variability,3);
for b = 1:cfg.n_bootstrap_variability
    sample = values(randi(n,n,1),:);
    cv = std(sample,0,1,'omitnan')./abs(mean(sample,1,'omitnan'));
    delta(b,:) = [cv(1)-cv(2),cv(1)-cv(3),cv(2)-cv(3)];
    ratio(b,:) = [cv(2)/cv(1),cv(3)/cv(1),cv(3)/cv(2)];
end
deltaCI = prctile(delta,[2.5 97.5])';
ratioCI = prctile(ratio,[2.5 97.5])';
stats = table({'Raw_vs_z';'Raw_vs_RVpeak';'z_vs_RVpeak'}, ...
    [cvValues(1)-cvValues(2);cvValues(1)-cvValues(3); ...
    cvValues(2)-cvValues(3)], ...
    [cvValues(2)/cvValues(1);cvValues(3)/cvValues(1); ...
    cvValues(3)/cvValues(2)],deltaCI(:,1),deltaCI(:,2), ...
    ratioCI(:,1),ratioCI(:,2),mean(delta<=0)',mean(ratio>=1)', ...
    'VariableNames',{'Comparison','CV_difference', ...
    'CV_ratio_second_over_first','Difference_CI_low','Difference_CI_high', ...
    'Ratio_CI_low','Ratio_CI_high','Bootstrap_p_difference', ...
    'Bootstrap_p_ratio'});
end

function S = loadPreprocessed(root,treatment,subject)
file = fullfile(root,treatment,subject, ...
    sprintf('%s_%s_outputs_preprocessing.mat',treatment,subject));
assert(isfile(file),['Required preprocessing output not found: %s\n' ...
    'Run workflows/fig3fil/batch_processing_fig3fil.m first.'],file);
S = load(file);
end

function y = smoothBySeconds(t,x,seconds)
dt = median(diff(t),'omitnan');
assert(isfinite(dt) && dt>0,'Could not estimate the trace sampling interval.');
window = max(3,round((seconds/60)/dt));
y = movmean(x,window,'omitnan');
end

function yi = interpolateTrace(t,y,target)
valid = isfinite(t) & isfinite(y);
[source,ia] = unique(t(valid),'stable');
values = y(valid); values = values(ia);
yi = interp1(source,values,target,'linear',NaN);
end

function A = positiveAUC(t,y,range,carryTail)
use = t>=range(1) & t<=range(2) & isfinite(t) & isfinite(y);
if nnz(use)<2, A=NaN; return; end
tx=t(use); yx=y(use);
[tx,ia]=unique(tx,'stable'); yx=yx(ia);
if carryTail && tx(end)<range(2)
    dt=median(diff(tx),'omitnan');
    if isfinite(dt) && dt>0
        tail=(tx(end)+dt:dt:range(2))';
        tx=[tx;tail];
        yx=[yx;repmat(mean(yx,'omitnan'),numel(tail),1)];
    end
end
segments=0.5.*(yx(1:end-1)+yx(2:end)).*diff(tx);
A=sum(max(segments,0),'omitnan');
end

function varargout = sameLength(varargin)
n = min(cellfun(@numel,varargin));
varargout = cell(size(varargin));
for i = 1:numel(varargin)
    value = varargin{i};
    varargout{i} = double(value(1:n));
    varargout{i} = varargout{i}(:);
end
end
